mapper.sql:
r.is_deleted = FALSE
AND r.tenant_code = #{tenantCode}

    AND r.channel_id = #{channelId}


    AND r.status = #{status}


    AND (r.caller ILIKE '%' || #{keyword} || '%'
         OR r.call_id ILIKE '%' || #{keyword} || '%'
         OR r.customer_no ILIKE '%' || #{keyword} || '%'
         OR r.ticket_no ILIKE '%' || #{keyword} || '%')

mapper.select:
SELECT COUNT(1) AS "total", COUNT(1) FILTER (WHERE r.status = 3) AS "finished", COUNT(1) FILTER (WHERE r.status = 2) AS "transferred", COUNT(1) FILTER (WHERE r.status = 4) AS "missed", COALESCE(ROUND(AVG(r.duration_seconds) FILTER (WHERE r.duration_seconds IS NOT NULL)), 0) AS "avgDuration" FROM channel_call_record r WHERE r.is_deleted = FALSE AND r.tenant_code = #{tenantCode}
AND r.channel_id = #{channelId}
AND r.create_time >= CURRENT_DATE
